const rows = $input.all().map(i => i.json)
  .filter(r => r.review_text && r.review_text.trim().length > 15);

// Anchor the window to the newest review, so older datasets still work
const dates = rows.map(r => new Date(r.date)).filter(d => !isNaN(d));
const newest = dates.length ? new Date(Math.max(...dates)) : new Date();
const cutoff = new Date(newest);
cutoff.setDate(cutoff.getDate() - 12 * 7);

const reviews = rows
  .filter(r => !r.date || new Date(r.date) >= cutoff)
  .slice(0, 200) // token safety
  .map((r, i) => ({ id: i + 1, rating: r.rating, text: r.review_text.trim().slice(0, 400) }));

return [{ json: {
  analysed: reviews.length,
  reviews_list: reviews,
  reviews_block: reviews.map(r => `[${r.id}] (${r.rating}★) ${r.text}`).join("\n")
}}];

let raw = String($input.first().json.text || $input.first().json.output || "");
const start = raw.indexOf("{");
if (start === -1) throw new Error("Review Intelligence returned no JSON object");
raw = raw.slice(start).trim();

// Closes unterminated strings and unbalanced braces/brackets (model sometimes drops the final brace)
function repair(s) {
  const stack = [];
  let inStr = false, esc = false;
  for (const ch of s) {
    if (inStr) {
      if (esc) esc = false;
      else if (ch === "\\") esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') inStr = true;
    else if (ch === "{" || ch === "[") stack.push(ch);
    else if (ch === "}" || ch === "]") stack.pop();
  }
  let out = s;
  if (inStr) out += '"';
  out = out.replace(/,\s*$/, "");
  while (stack.length) out += stack.pop() === "{" ? "}" : "]";
  return out;
}

let data;
try {
  data = JSON.parse(raw);
} catch (e1) {
  try {
    data = JSON.parse(raw.slice(0, raw.lastIndexOf("}") + 1)); // drop trailing text / code fences
  } catch (e2) {
    try {
      data = JSON.parse(repair(raw.replace(/```\s*$/, "").trim()));
    } catch (e3) {
      throw new Error("Review Intelligence returned invalid JSON: " + e1.message);
    }
  }
}

if (data.themes.length > 5) throw new Error("More than 5 themes");
if (data.top_themes.length !== 3) throw new Error("Need exactly 3 top themes");
if (data.quotes.length !== 3) throw new Error("Need exactly 3 quotes");

// Anti-hallucination check against the source reviews
// Strip prompt artifacts the model sometimes copies: "[12]" ids and "(4★)" rating tags, wrapping quotes
const clean = t => String(t || "")
  .replace(/^\s*(\[\d+\]\s*)?(\(\s*\d\s*★\s*\)\s*)?/, "")
  .replace(/^["“”']+|["“”']+$/g, "")
  .trim();
const norm = t => String(t || "").toLowerCase().replace(/\s+/g, " ").trim();
const source = norm($('Clean and filter').first().json.reviews_list.map(r => r.text).join(" "));
const isReal = quote => {
  const n = norm(quote).replace(/\.{3}$|…$/, "").trim();
  return n.length > 0 && source.includes(n.slice(0, 40));
};
data.quotes.forEach(q => { q.quote = clean(q.quote); q.verified = isReal(q.quote); });
if (data.fee_issue && Array.isArray(data.fee_issue.evidence)) {
  data.fee_issue.evidence.forEach(e => { e.quote = clean(e.quote); });
}
const bad = data.quotes.filter(q => !q.verified);
if (bad.length) throw new Error("Unverified quote found: " + bad.map(q => '"' + q.quote.slice(0, 60) + '"').join(", "));

return [{ json: data }];

const LIMIT = 250;
const raw = String($json.output || $json.text || '').trim();
// Count only real words (tokens containing a letter or digit), so markdown like -, ###, ** is not counted
const isWord = t => /[\p{L}\p{N}]/u.test(t);
const countWords = s => s.split(/\s+/).filter(isWord).length;
let text = raw;
let wc = countWords(text);
let trimmed = false;
if (wc > LIMIT) {
  // Drop whole lines from the end until within the limit, keeping structure intact
  const lines = text.split('\n');
  while (lines.length > 1 && countWords(lines.join('\n')) > LIMIT) lines.pop();
  text = lines.join('\n').trim();
  // Fallback: hard cut by words if a single line is still too long
  if (countWords(text) > LIMIT) {
    const toks = text.split(/(\s+)/);
    let n = 0; const out = [];
    for (const t of toks) { if (isWord(t)) { if (n >= LIMIT) break; n++; } out.push(t); }
    text = out.join('').trim();
  }
  wc = countWords(text);
  trimmed = true;
}
if (!text) throw new Error('Weekly pulse is empty');
return [{ json: { weekly_pulse: text, word_count: wc, trimmed } }];

const ALLOWED = [
  'https://www.amfiindia.com/investor/knowledge-center-info?zoneName=expenseRatio',
  'https://www.amfiindia.com/ter-of-mf-schemes',
  'https://www.sebi.gov.in/sebi_data/faqfiles/sep-2024/1727242783639.pdf',
  'https://groww.in/pricing'
];
let raw = $input.first().json.output || $input.first().json.text || '';
raw = String(raw).replace(/```json|```/g, '').trim();
const fee = JSON.parse(raw);
const bullets = (fee.bullets || []).map(b => String(b).trim()).filter(Boolean);
if (bullets.length === 0) throw new Error('Fee explainer returned no bullets');
if (bullets.length > 6) throw new Error('Fee explainer has more than 6 bullets');

let links = (fee.source_links || []).filter(l => ALLOWED.includes(l));
for (const l of ALLOWED) { if (links.length >= 2) break; if (!links.includes(l)) links.push(l); }
links = links.slice(0, 2);

const analysis = $('Parse and Validate').first().json;
const pulse = String($('Pulse Word Check').first().json.weekly_pulse || '');
const date = $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd');
const feeName = fee.fee_name || analysis.fee_issue.fee_name;
const misunderstanding = analysis.fee_issue.misunderstanding || '';
const topThemes = analysis.top_themes || [];

// ---------- Parse the pulse into sections ----------
const clean = s => String(s).replace(/\*\*|__/g, '').replace(/^#+\s*/, '').trim();
const sections = [];
let cur = null;
for (const line0 of pulse.split('\n')) {
  const line = line0.trim();
  if (!line) continue;
  const KNOWN = /^(?:\d+[.)]\s*)?(top themes|what users are saying|key observation|action ideas)\s*:?$/i;
  const known = clean(line).match(KNOWN);
  if (known) { cur = { title: clean(line).replace(/^\d+[.)]\s*/, '').replace(/:$/, ''), items: [] }; sections.push(cur); continue; }
  const bulletMatch = line.match(/^(?:[-*•]|\d+[.)])\s+(.*)$/);
  const bare = clean(line).replace(/:$/, '');
  const isHeading = !bulletMatch && !/^["“]/.test(bare) && (/^#+\s/.test(line) || (bare.length <= 45 && !/[.!?"”)]$/.test(bare) && !/[.!?]\s/.test(bare) && !/:/.test(bare)));
  if (isHeading) { cur = { title: clean(line).replace(/^\d+\.\s*/, '').replace(/:$/, ''), items: [] }; sections.push(cur); continue; }
  if (!cur) { cur = { title: '', items: [] }; sections.push(cur); }
  const isQuote = /^["“]/.test(line);
  cur.items.push(bulletMatch ? { type: 'li', text: clean(bulletMatch[1]) } : isQuote ? { type: 'li', text: clean(line) } : { type: 'p', text: clean(line) });
}

// ---------- HTML (Gmail draft + approval email) ----------
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const H2 = 'style="font-size:18px;color:#1a1a1a;margin:24px 0 8px;border-bottom:2px solid #00b386;padding-bottom:4px"';
const H3 = 'style="font-size:15px;color:#00875f;margin:18px 0 6px"';
const P = 'style="margin:6px 0;line-height:1.5"';
const UL = 'style="margin:6px 0 6px 20px;padding:0;line-height:1.5"';
const renderItems = items => {
  let out = ''; let inList = false;
  for (const it of items) {
    if (it.type === 'li') { if (!inList) { out += '<ul ' + UL + '>'; inList = true; } out += '<li style="margin:4px 0">' + esc(it.text) + '</li>'; }
    else { if (inList) { out += '</ul>'; inList = false; } out += '<p ' + P + '>' + esc(it.text) + '</p>'; }
  }
  if (inList) out += '</ul>';
  return out;
};
const pulseHtml = sections.map(s => (s.title ? '<h3 ' + H3 + '>' + esc(s.title) + '</h3>' : '') + renderItems(s.items)).join('');
const explainerHtml =
  '<h3 ' + H3 + '>Understanding the ' + esc(feeName) + ' on Groww</h3>' +
  '<ul ' + UL + '>' + bullets.map(b => '<li style="margin:4px 0">' + esc(b) + '</li>').join('') + '</ul>' +
  '<p ' + P + '><b>Sources:</b></p><ul ' + UL + '>' + links.map(l => '<li style="margin:4px 0"><a href="' + esc(l) + '">' + esc(l) + '</a></li>').join('') + '</ul>' +
  '<p style="margin:10px 0;color:#666;font-size:13px"><i>Last checked: ' + esc(date) + '</i></p>';
const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;max-width:680px">' +
  '<h2 ' + H2 + '>Weekly Product Pulse — ' + esc(date) + '</h2>' + pulseHtml +
  '<h2 ' + H2 + '>Customer Clarification (reusable support snippet)</h2>' + explainerHtml +
  '</div>';

// ---------- Neat plain text (Google Doc) ----------
const RULE = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━';
const docLines = [
  '', RULE, 'WEEKLY PRODUCT PULSE LOG — ' + date, RULE, '',
  'TOP THEMES', ...topThemes.map((t, i) => '   ' + (i + 1) + '. ' + t), '',
  'WEEKLY PULSE'
];
for (const s of sections) {
  if (s.title) docLines.push('', '▸ ' + s.title);
  for (const it of s.items) docLines.push(it.type === 'li' ? '   • ' + it.text : '   ' + it.text);
}
docLines.push(
  '', 'IDENTIFIED FEE ISSUE',
  '   Fee: ' + feeName,
  '   What users misunderstand: ' + misunderstanding,
  '', 'EXPLANATION (support snippet)', ...bullets.map(b => '   • ' + b),
  '', 'SOURCES', ...links.map(l => '   • ' + l),
  '', 'Last checked: ' + date, ''
);
const docText = docLines.join('\n');

const explainerText = ['Understanding the ' + feeName + ' on Groww', ...bullets.map(b => '- ' + b), 'Sources:', ...links.map(l => '- ' + l), 'Last checked: ' + date].join('\n');
const record = {
  date,
  top_themes: topThemes,
  weekly_pulse: pulse,
  identified_fee_issue: { fee_name: feeName, misunderstanding },
  explanation_bullets: bullets,
  source_links: links
};
const subject = 'Weekly Product Pulse + Customer Clarification — ' + date;
const approvalHtml = '<p style="font-family:Arial,sans-serif"><b>Review before logging and drafting.</b> Approve to append this to the Google Doc and create the Gmail draft.</p><p style="font-family:Arial,sans-serif"><b>Subject:</b> ' + esc(subject) + '</p><hr>' + emailHtml;

return [{ json: { record, subject, email_body: emailHtml, email_html: emailHtml, explainer_text: explainerText, approval_html: approvalHtml, doc_entry: docText } }];
